    topology: "Evidence join + gate",
    accent: "#f0a05a",
    yaml: "apiVersion: ladder.dev/v1alpha1\nkind: Workflow\nmetadata:\n  name: positioning-launch-experiment\n  title: Positioning + launch experiment\n  description: Ground the message in customer urgency and alternatives, then design a measurable launch test.\n  version: 1.0.0\nspec:\n  objective: Produce differentiated positioning and a falsifiable launch experiment.\n  policies:\n    maxConcurrency: 3\n    onFailure: preserve-completed\n    requireApprovalFor: []\n  nodes:\n    - id: brief\n      kind: input\n      name: Market brief\n      summary: Product, target market, evidence, alternatives, constraints, and launch goal.\n      position:\n        x: 100\n        y: 220\n    - id: perspective-a\n      kind: agent\n      name: Customer urgency\n      summary: Identify the beachhead user, trigger, pain, and proof needed.\n      role: Customer insight researcher\n      prompt: Define the highest-urgency segment, triggering event, current workaround, desired progress,\n        and proof that would change behavior.\n      capabilities:\n        skills:\n          - customer-research\n        tools:\n          - read\n          - search\n        permissions:\n          - read-only\n      outputSchema:\n        type: object\n        required:\n          - findings\n          - evidence\n        properties:\n          findings:\n            type: array\n            items:\n              type: string\n          evidence:\n            type: array\n            items:\n              type: string\n      position:\n        x: 380\n        y: 90\n    - id: perspective-b\n      kind: agent\n      name: Competitive frame\n      summary: Map alternatives and credible differentiation.\n      role: Market intelligence strategist\n      prompt: Map direct and indirect alternatives. Identify defensible differences, table stakes, and\n        claims the evidence cannot support.\n      capabilities:\n        skills:\n          - competitive-analysis\n        tools:\n          - read\n          - search\n        permissions:\n          - read-only\n      outputSchema:\n        type: object\n        required:\n          - findings\n          - risks\n        properties:\n          findings:\n            type: array\n            items:\n              type: string\n          risks:\n            type: array\n            items:\n              type: string\n      position:\n        x: 380\n        y: 350\n    - id: join\n      kind: join\n      name: Perspective barrier\n      summary: Wait for both independent perspectives.\n      config:\n        join: all\n      position:\n        x: 660\n        y: 220\n    - id: synthesis\n      kind: agent\n      name: Launch strategy\n      summary: Turn market evidence into message, channel, and test.\n      role: Go-to-market strategist\n      prompt: Write positioning, proof points, objections, beachhead channel, experiment design, success\n        threshold, and stop condition.\n      capabilities:\n        skills:\n          - go-to-market\n        tools:\n          - read\n        permissions:\n          - read-only\n      outputSchema:\n        type: object\n        required:\n          - recommendation\n          - actions\n          - openQuestions\n        properties:\n          recommendation:\n            type: string\n          actions:\n            type: array\n            items:\n              type: string\n          openQuestions:\n            type: array\n            items:\n              type: string\n      position:\n        x: 900\n        y: 150\n    - id: evaluation\n      kind: evaluate\n      name: Message credibility gate\n      summary: Check the recommendation against its evidence and contract.\n      role: GTM review lead\n      prompt: Pass only when the positioning is specific, differentiated, evidence-backed, and paired with\n        a measurable experiment.\n      capabilities:\n        skills:\n          - evaluation\n        tools:\n          - read\n        permissions:\n          - read-only\n      outputSchema:\n        type: object\n        required:\n          - score\n          - passed\n          - reasons\n        properties:\n          score:\n            type: number\n          passed:\n            type: boolean\n          reasons:\n            type: array\n            items:\n              type: string\n      config:\n        threshold: 0.85\n      position:\n        x: 900\n        y: 330\n    - id: output\n      kind: output\n      name: Launch experiment\n      summary: Positioning, proof, channel hypothesis, experiment, and decision threshold.\n      position:\n        x: 1180\n        y: 220\n  edges:\n    - id: e1\n      from: brief\n      to: perspective-a\n      kind: data\n      contract: Brief\n    - id: e2\n      from: brief\n      to: perspective-b\n      kind: data\n      contract: Brief\n    - id: e3\n      from: perspective-a\n      to: join\n      kind: data\n      contract: EvidenceSet\n    - id: e4\n      from: perspective-b\n      to: join\n      kind: data\n      contract: RiskSet\n    - id: e5\n      from: join\n      to: synthesis\n      kind: dependency\n    - id: e6\n      from: synthesis\n      to: evaluation\n      kind: data\n      contract: Recommendation\n    - id: e7\n      from: evaluation\n      to: output\n      kind: control\n      condition: passed == true\n",
